-- Evolução Visual (PatientMetric) + PatientExam (schema Prisma)

CREATE TABLE "PatientMetric" (
    "id" TEXT NOT NULL,
    "patientId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "value" DOUBLE PRECISION NOT NULL,
    "date" TIMESTAMP(3) NOT NULL,
    "isAutoGenerated" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "PatientMetric_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "PatientMetric_patientId_date_idx" ON "PatientMetric"("patientId", "date");
CREATE INDEX "PatientMetric_name_idx" ON "PatientMetric"("name");

ALTER TABLE "PatientMetric" ADD CONSTRAINT "PatientMetric_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE "PatientExam" (
    "id" TEXT NOT NULL,
    "patientId" TEXT NOT NULL,
    "title" TEXT,
    "fileUrl" TEXT NOT NULL,
    "fileType" TEXT NOT NULL,
    "aiSummary" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "PatientExam_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "PatientExam_patientId_idx" ON "PatientExam"("patientId");

ALTER TABLE "PatientExam" ADD CONSTRAINT "PatientExam_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE CASCADE ON UPDATE CASCADE;
